INSERT INTO specifications (specification_id, parameter_id, identity_code, icf_code, needs_code, medical_code, state, design_scale, convergence_id, confidence_dimensions_present, confidence_dimensions_absent, confidence_synthesis_basis, gap_register_id, not_applicable_rationale, tier_basis, governing_refs, rule_version, derivation_sha, code_floor_only, value_min, value_max, value_unit, value_note, value_notations, falsification_condition, has_unverified_sources, all_sources_disqualified, regulatory_stratum_only, rests_on_proxy_inference, marker, functional_basis, derivation_paths, derivation_rationale, cultural_claim_anchor, created_at, created_by_session, updated_at, updated_by_session) VALUES (15, 3, NULL, NULL, 'A-EFFORT', NULL, 'provisional', 'universal', 15, '["Tier 4-5 standards (7)", "Tier 6 statutory codes (19)", "Anchoring-tier findings supplying direction (5: CO1+T2)"]', '["No source states a value for this parameter at an anchoring tier -- the threshold is regulatory and the direction is inferred, so this is a PROXY determination and not a best-practice claim"]', 'Threshold from the regulatory stratum (>=1 T4 international standard present (§2.3; the clause''s ''value directly addressing the parameter'' is unverified — value extraction pending)), direction from measured findings. A proxy inference under the owner statement of 2026-09-16, marked as one.', NULL, NULL, 'T4-6-only-threshold+CO1+T2-direction(proxy_inference)', NULL, 'pilot-4', '3ebcfe9e0f3539aaaf6ac45568ff54307e76f9b396c163af513ed5ce73c50665', 0, NULL, 5.0, '%', 'composed from 10 of 34 governing claims: 24 state no parsable numeric bound (''12%'', ''1:10'', ''1:12'', ''1:15'', ''1:16'', ''1:20'', ''1:6'', ''5%'', ''6%'', ''8%'', ''viisi prosenttia'') and contribute to the cell''s STATE but not to this interval; value presented in 2 notations of one quantity (owner ruling 2026-09-17: present both, never choose)', '[{"notation": "%", "min": null, "max": "5", "stated": true, "exact": true}, {"notation": "rise:run ratio", "min": null, "max": "1:20", "stated": true, "exact": true}]', 'Overturned if a source states a value for this parameter at an anchoring tier (the cell then rests on that, not on a proxy), if the findings supplying direction are retracted or re-graded off `finding`, or if the cited threshold editions are superseded. It does NOT become a best-practice claim by more codes agreeing (§2.7), and the proxy step is degenerate without the threshold: ''best outcomes'' alone resolves to the gentlest gradient physically possible, which for a ramp is not a ramp.', 1, 0, 0, 1, '○', NULL, 'population_only', 'no identity_icf_map row characterises this lens, so no function path exists to meet the population path; recorded as a single-path determination per H2. This is NOT a downgrade: the absence of a functional derivation never reduces a population-derived claim (DR-2026-07-13, the cultural-claim protection).', NULL, '2026-10-22 05:00:00', 'session_2026-10-22-regression', '2026-10-22 05:00:00', 'session_2026-10-22-regression');
